select distinct p.code from rbac_role r join rbac_role_permission rp on rp.role_id = r.id and rp.effect = 'ALLOW' and rp.deleted_at is null join rbac_permission p on p.id = rp.permission_id and p.status = 'ENABLED' where r.code in
#{role}
and r.status = 'ENABLED' and r.deleted_at is null order by p.code
